
/*
  CardioAccess AI
  Shared formatting and presentation helpers

  These functions format data already available
  to the frontend. They do not generate clinical
  predictions, referral actions, or database IDs.
*/

/* -----------------------------------------
   CASE IDENTIFIERS
----------------------------------------- */

export function caseCode(n) {
  // Compatibility helper for existing UI code.
  // Real case codes are generated by the database.
  return `CA-2026-${String(n).padStart(6, "0")}`;
}

export function referralCode(caseId) {
  // Legacy compatibility only.
  // This does not create a referral record.
  const value = String(caseId || "");
  return value ? `RF-${value.slice(3)}` : "—";
}

/* -----------------------------------------
   DATE AND TIME FORMATTING
----------------------------------------- */

export function formatWhen(iso) {
  if (!iso) {
    return {
      day: "—",
      time: "—",
      both: "—",
      clock: "—",
    };
  }

  const date = new Date(iso);

  if (Number.isNaN(date.getTime())) {
    return {
      day: "—",
      time: "—",
      both: "—",
      clock: "—",
    };
  }

  const day = date.toLocaleDateString("en-GB", {
    day: "2-digit",
    month: "short",
    year: "numeric",
  });

  const time = date.toLocaleTimeString("en-GB", {
    hour: "2-digit",
    minute: "2-digit",
  });

  const clock = date.toLocaleTimeString("en-GB", {
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
  });

  return {
    day,
    time,
    both: `${day}, ${time}`,
    clock,
  };
}

/* -----------------------------------------
   MODALITY FORMATTING
----------------------------------------- */

export function modalityLabel(modality) {
  if (modality === "both") {
    return "Multimodal ECG + Echo";
  }

  if (modality === "ecg") {
    return "ECG";
  }

  if (modality === "echo") {
    return "Echo";
  }

  return "Not recorded";
}

/* -----------------------------------------
   TRIAGE AND CONFIDENCE HELPERS
----------------------------------------- */

export function triageOf(record) {
  if (!record) return null;

  const triage = record.triage;

  if (typeof triage === "string") {
    return [
      "Normal",
      "Needs Review",
      "Urgent Referral",
    ].includes(triage)
      ? triage
      : null;
  }

  if (
    triage &&
    typeof triage === "object"
  ) {
    const category =
      triage.category ||
      triage.label ||
      triage.triage_category ||
      null;

    return [
      "Normal",
      "Needs Review",
      "Urgent Referral",
    ].includes(category)
      ? category
      : null;
  }

  return null;
}

export function isLowConfidence(record) {
  if (!record) return false;

  return (
    record.lowConfidence === true ||
    record.confidenceFlag === "low" ||
    record.confidenceFlag === "low_confidence" ||
    (
      Array.isArray(record.lowConfidenceModalities) &&
      record.lowConfidenceModalities.length > 0
    )
  );
}

export function needsProfessionalReview(record) {
  const triage = triageOf(record);

  return (
    triage === "Needs Review" ||
    triage === "Urgent Referral" ||
    isLowConfidence(record)
  );
}

/* -----------------------------------------
   CASE STATUS
----------------------------------------- */

export function caseStatus(record) {
  const status = record?.status;

  switch (status) {
    case "draft":
      return "Draft";

    case "queued":
      return "Queued";

    case "processing":
      return "Processing";

    case "completed":
      return "Completed";

    case "partially_completed":
      return "Partially Completed";

    case "failed":
      return "Failed";

    default:
      return "—";
  }
}

/* -----------------------------------------
   SCREENING CATEGORY
----------------------------------------- */

export function categoryOf(record) {
  if (!record) return "—";

  const status = record.status;

  if (status === "draft") {
    return "Pending analysis";
  }

  if (status === "queued") {
    return "Queued";
  }

  if (status === "processing") {
    return "Processing";
  }

  if (status === "failed") {
    return "Analysis failed";
  }

  const triage = triageOf(record);

  if (triage) {
    return triage;
  }

  // ECG-only classification is not a triage decision.
  const ecgClass =
    record.ecg?.predictedClass ||
    record.ecg?.predicted_class ||
    record.ecgResult?.predictedClass ||
    record.ecgResult?.predicted_class ||
    null;

  if (ecgClass) {
    return ecgClass;
  }

  if (status === "partially_completed") {
    return "Partially completed";
  }

  if (status === "completed") {
    return "Result unavailable";
  }

  return "Not analyzed";
}

/* -----------------------------------------
   PATIENT / CASE DISPLAY
----------------------------------------- */

export function patientOf(record) {
  if (!record) {
    return {
      id: "—",
      name: "Pseudonymous patient",
      age: "—",
      sex: "—",
      clinical: "",
      date: "",
    };
  }

  /*
    The current cases table does not contain
    patient_name, patient_alias, age, or sex.

    Preserve optional display values only if
    an authorized backend response provides them.
  */

  const patientId =
    record.patientId ||
    record.patient_code ||
    record.caseCode ||
    record.case_code ||
    "—";

  const patientName =
    record.patientName ||
    record.patientAlias ||
    record.patient_alias ||
    "Pseudonymous patient";

  return {
    id: patientId,
    name: patientName,
    age: record.age ?? "—",
    sex: record.sex || "—",
    clinical:
      record.clinical ||
      record.clinical_notes ||
      record.notes ||
      "",
    date:
      record.screeningDate ||
      record.createdAt?.slice(0, 10) ||
      record.created_at?.slice(0, 10) ||
      "",
  };
}

/* -----------------------------------------
   EF-BASED SCREENING CATEGORY
----------------------------------------- */

export function efBand(ef) {
  if (
    ef === null ||
    ef === undefined ||
    ef === "" ||
    !Number.isFinite(Number(ef))
  ) {
    return null;
  }

  const value = Number(ef);

  if (value > 50) {
    return "Normal";
  }

  if (value > 40) {
    return "Needs Review";
  }

  return "Urgent Referral";
}

/* -----------------------------------------
   SCREENING GUIDANCE
----------------------------------------- */

export function nextAction(record) {
  if (!record) {
    return "No screening information is available.";
  }

  if (record.status === "draft") {
    return (
      "This case is saved as a draft. " +
      "Analysis has not been requested and " +
      "no screening prediction is available."
    );
  }

  if (record.status === "queued") {
    return (
      "The case is queued for analysis. " +
      "Results will become available when " +
      "backend processing completes."
    );
  }

  if (record.status === "processing") {
    return (
      "The backend is processing this case. " +
      "Wait for the analysis status to update."
    );
  }

  if (record.status === "failed") {
    return (
      "Analysis could not be completed. " +
      "Review the error information and " +
      "follow the applicable retry procedure."
    );
  }

  if (record.status === "partially_completed") {
    return (
      "Analysis is partially completed. " +
      "Review only the outputs actually available. " +
      "Do not assume missing results or triage categories."
    );
  }

  const triage = triageOf(record);

  if (triage === "Urgent Referral") {
    return (
      "This screening has an Urgent Referral " +
      "flag and requires priority professional " +
      "review. No referral is automatically " +
      "created or sent."
    );
  }

  if (triage === "Needs Review") {
    return (
      "This screening is flagged in Screening " +
      "Review for professional assessment. " +
      "A qualified healthcare professional " +
      "determines the appropriate next steps."
    );
  }

  if (isLowConfidence(record)) {
    return (
      "This screening contains a low-confidence " +
      "result. Review the uncertainty information " +
      "and available findings before making " +
      "clinical decisions."
    );
  }

  if (triage === "Normal") {
    return (
      "The available screening result is " +
      "categorized as Normal. This is not " +
      "a definitive diagnosis or a guarantee " +
      "that cardiovascular disease is absent."
    );
  }

  if (
    record.ecg ||
    record.ecgResult
  ) {
    return (
      "An ECG classification is available for " +
      "screening support. ECG-only analysis does " +
      "not automatically assign a triage category."
    );
  }

  return (
    "Review the available screening information. " +
    "No clinical conclusion should be inferred " +
    "from missing analysis results."
  );
}

/* -----------------------------------------
   USER INITIALS
----------------------------------------- */

export function initials(name) {
  if (typeof name !== "string" || !name.trim()) {
    return "";
  }

  return name
    .trim()
    .split(/\s+/)
    .filter(
      (part) =>
        part &&
        !["Dr.", "Dr"].includes(part)
    )
    .slice(0, 2)
    .map((part) => part[0])
    .join("")
    .toUpperCase();
}

/* -----------------------------------------
   PASSWORD VALIDATION
----------------------------------------- */

export function passwordChecks(password, confirm) {
  const value = String(password || "");
  const confirmation = String(confirm || "");

  return {
    length: value.length >= 8,
    letterNumber:
      /[A-Za-z]/.test(value) &&
      /\d/.test(value),
    match:
      value.length > 0 &&
      value === confirmation,
  };
}

/* -----------------------------------------
   EMAIL VALIDATION
----------------------------------------- */

export function isEmail(value) {
  if (typeof value !== "string") {
    return false;
  }

  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(
    value.trim()
  );
}

/* -----------------------------------------
   FILE EXTENSION VALIDATION
----------------------------------------- */

export const ECG_ACCEPT = [
  ".zip",
  ".csv",
  ".hea",
  ".dat",
];

export const ECHO_ACCEPT = [
  ".avi",
  ".mp4",
  ".nii",
  ".gz",
];

export function extensionOk(name, allowed) {
  if (
    typeof name !== "string" ||
    !Array.isArray(allowed)
  ) {
    return false;
  }

  const lower = name.toLowerCase();

  return allowed.some((ext) =>
    lower.endsWith(ext.toLowerCase())
  );
}

/* -----------------------------------------
   TEXT FILE DOWNLOAD
----------------------------------------- */

export function downloadText(filename, text) {
  const blob = new Blob(
    [String(text ?? "")],
    {
      type: "text/plain;charset=utf-8",
    }
  );

  const url = URL.createObjectURL(blob);

  const link = document.createElement("a");

  link.href = url;
  link.download = filename;

  document.body.appendChild(link);
  link.click();
  link.remove();

  URL.revokeObjectURL(url);
}
